        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # pre1 and pre2 are either None or list of identifiers
        # Version without pre-release sorts after version with pre-release
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release sorts after
        if pre2 is None:
            return -1  # version with pre-release sorts before

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric, compare numerically
                result = int(id1) - int(id2)
                if result != 0:
                    return result if result < 0 else 1
            elif is_num1:
                # Numeric sorts before non-numeric
                return -1
            elif is_num2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All shared identifiers are equal, fewer sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease = parse_version(version)

        # Create a sortable key: (major, minor, patch, prerelease_tuple, original_index)
        # For pre-release, we need a tuple that sorts correctly
        if prerelease is None:
            # No pre-release: sorts after any pre-release of same base version
            prerelease_key = (1,)  # sorts after (0, ...)
        else:
            # Has pre-release: convert to sortable form
            parts_key = []
            for part in prerelease:
                if part.isdigit():
                    # Numeric identifiers sort before non-numeric
                    parts_key.append((0, int(part)))
                else:
                    # Non-numeric identifiers
                    parts_key.append((1, part))
            prerelease_key = (0, tuple(parts_key))

        return (major, minor, patch, prerelease_key, index)

    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for i, v in sorted_versions]

